create or replace function public.credit_affiliate_wager_commission_atomic(p_referred_user_id uuid,p_wager_amount numeric,p_wager_ref text,p_game text,p_rate numeric default 0.005) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_referral public.affiliate_referrals%rowtype; v_affiliate_user_id uuid; v_amount numeric; v_ref text; v_tx_id uuid; v_balance numeric; begin if p_referred_user_id is null or coalesce(p_wager_amount,0)<=0 or nullif(trim(p_wager_ref),'') is null then return jsonb_build_object('ok',true,'credited',false,'reason','INVALID_OR_EMPTY_INPUT'); end if; v_amount:=round(p_wager_amount*greatest(0,least(coalesce(p_rate,0.005),1)),2); if v_amount<=0 then return jsonb_build_object('ok',true,'credited',false,'reason','BELOW_MINIMUM'); end if; v_ref:='aff_wager:'||trim(p_wager_ref); perform pg_advisory_xact_lock(hashtextextended(v_ref,0)); if exists(select 1 from public.affiliate_commissions where ref_id=v_ref) then return jsonb_build_object('ok',true,'credited',true,'idempotent',true,'ref_id',v_ref); end if; select r.* into v_referral from public.affiliate_referrals r where r.referred_user_id=p_referred_user_id order by r.created_at asc limit 1 for update; if not found then return jsonb_build_object('ok',true,'credited',false,'reason','NO_REFERRAL'); end if; v_affiliate_user_id:=coalesce(v_referral.affiliate_user_id,v_referral.referrer_id); if v_affiliate_user_id is null or not exists(select 1 from public.affiliates a where a.user_id=v_affiliate_user_id and a.status='active') then return jsonb_build_object('ok',true,'credited',false,'reason','AFFILIATE_INACTIVE'); end if; insert into public.balances(user_id,balance,bonus_balance,locked_balance,commission_balance,currency) values(v_affiliate_user_id,0,0,0,0,'MXN') on conflict(user_id) do nothing; select commission_balance into v_balance from public.balances where user_id=v_affiliate_user_id for update; insert into public.affiliate_commissions(affiliate_user_id,referred_user_id,amount,reason,ref_id,status,metadata) values(v_affiliate_user_id,p_referred_user_id,v_amount,'wager_commission',v_ref,'pending',jsonb_build_object('wager_amount',p_wager_amount,'wager_ref',p_wager_ref,'game',p_game,'rate',p_rate)); update public.balances set commission_balance=round(coalesce(commission_balance,0)+v_amount,2),updated_at=now() where user_id=v_affiliate_user_id; v_tx_id:=gen_random_uuid(); insert into public.transactions(id,user_id,amount,type,status,method,reason,ref_id,metadata,created_at,updated_at) values(v_tx_id,v_affiliate_user_id,v_amount,'bonus'::transaction_type,'completed'::transaction_status,'internal_game'::transaction_method,'affiliate_wager_commission',v_ref,jsonb_build_object('referred_user_id',p_referred_user_id,'wager_amount',p_wager_amount,'wager_ref',p_wager_ref,'game',p_game,'commission_balance',round(coalesce(v_balance,0)+v_amount,2)),now(),now()); update public.affiliate_commissions set status='credited',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('credited_at',now(),'tx_id',v_tx_id) where ref_id=v_ref; update public.affiliate_referrals set total_commission=round(coalesce(total_commission,0)+v_amount,2),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('last_wager_commission_at',now(),'last_wager_ref',p_wager_ref) where id=v_referral.id; return jsonb_build_object('ok',true,'credited',true,'idempotent',false,'amount',v_amount,'affiliate_user_id',v_affiliate_user_id,'tx_id',v_tx_id,'ref_id',v_ref); end; $$;
create or replace function public.record_wager_effects(p_user_id uuid,p_wager_amount numeric,p_wager_ref text,p_game text default null,p_affiliate_rate numeric default 0.005) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_existing public.wager_progress_ledger%rowtype; v_claim public.promo_claims%rowtype; v_streak public.daily_streak_claims%rowtype; v_profile public.profiles%rowtype; v_required numeric:=0; v_progress numeric:=0; v_next numeric:=0; v_bonus numeric:=0; v_release jsonb; v_affiliate jsonb; v_rollover jsonb:=jsonb_build_object('status','none'); v_result jsonb; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if coalesce(p_wager_amount,0)<=0 then raise exception 'INVALID_WAGER_AMOUNT'; end if; if nullif(trim(p_wager_ref),'') is null then raise exception 'WAGER_REF_REQUIRED'; end if; perform pg_advisory_xact_lock(hashtextextended('wager_effects:'||trim(p_wager_ref),0)); select * into v_existing from public.wager_progress_ledger where wager_ref=trim(p_wager_ref); if found then return coalesce(v_existing.result,'{}'::jsonb)||jsonb_build_object('ok',true,'idempotent',true); end if; v_affiliate:=public.credit_affiliate_wager_commission_atomic(p_user_id,p_wager_amount,p_wager_ref,p_game,p_affiliate_rate); if coalesce(v_affiliate->>'ok','false')<>'true' then raise exception 'AFFILIATE_WAGER_EFFECT_FAILED'; end if; select * into v_claim from public.promo_claims where user_id=p_user_id and status='applied' order by claimed_at desc limit 1 for update; if found and coalesce(v_claim.wagering_required,0)>0 then v_required:=v_claim.wagering_required; v_progress:=coalesce(v_claim.wagering_progress,0); v_next:=least(v_required,v_progress+p_wager_amount); if v_next>=v_required then select coalesce(bonus_balance,0) into v_bonus from public.balances where user_id=p_user_id for update; if v_bonus>0 then v_release:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>v_bonus,p_delta_bonus=>-v_bonus,p_delta_locked=>0,p_reason=>'promo_bonus_release',p_ref_id=>'promo_clear:'||v_claim.id::text,p_method=>'internal_game',p_metadata=>jsonb_build_object('claim_id',v_claim.id,'completed_by_wager_ref',p_wager_ref)); if coalesce(v_release->>'ok','false')<>'true' then raise exception 'PROMO_RELEASE_FAILED'; end if; end if; update public.promo_claims set wagering_progress=v_required,status='completed',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('completed_at',now(),'completed_by','atomic_wager','last_wager_ref',p_wager_ref,'last_game',p_game) where id=v_claim.id; v_rollover:=jsonb_build_object('status','completed','source','promo','claim_id',v_claim.id,'required',v_required,'progress',v_required,'released',v_bonus); else update public.promo_claims set wagering_progress=v_next,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('last_wager_ref',p_wager_ref,'last_game',p_game,'last_wager_amount',p_wager_amount,'last_wager_at',now()) where id=v_claim.id; v_rollover:=jsonb_build_object('status','progressed','source','promo','claim_id',v_claim.id,'required',v_required,'progress',v_next); end if; else select * into v_profile from public.profiles where id=p_user_id for update; if found and coalesce(v_profile.wager_required,0)>coalesce(v_profile.wager_progress,0) then select * into v_streak from public.daily_streak_claims where user_id=p_user_id and wagering_required>wagering_progress order by claim_date desc limit 1 for update; if found then v_required:=v_profile.wager_required; v_progress:=coalesce(v_profile.wager_progress,0); v_next:=least(v_required,v_progress+p_wager_amount); if v_next>=v_required then select coalesce(bonus_balance,0) into v_bonus from public.balances where user_id=p_user_id for update; if v_bonus>0 then v_release:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>v_bonus,p_delta_bonus=>-v_bonus,p_delta_locked=>0,p_reason=>'daily_streak_bonus_release',p_ref_id=>'streak_clear:'||v_streak.id::text,p_method=>'internal_game',p_metadata=>jsonb_build_object('daily_streak_claim_id',v_streak.id,'completed_by_wager_ref',p_wager_ref)); if coalesce(v_release->>'ok','false')<>'true' then raise exception 'STREAK_RELEASE_FAILED'; end if; end if; update public.profiles set wager_required=0,wager_progress=0,updated_at=now() where id=p_user_id; update public.daily_streak_claims set wagering_progress=v_required where id=v_streak.id; v_rollover:=jsonb_build_object('status','completed','source','daily_streak','claim_id',v_streak.id,'required',v_required,'progress',v_required,'released',v_bonus); else update public.profiles set wager_progress=v_next,updated_at=now() where id=p_user_id; update public.daily_streak_claims set wagering_progress=v_next where id=v_streak.id; v_rollover:=jsonb_build_object('status','progressed','source','daily_streak','claim_id',v_streak.id,'required',v_required,'progress',v_next); end if; end if; end if; end if; v_result:=jsonb_build_object('ok',true,'idempotent',false,'wager_ref',trim(p_wager_ref),'wager_amount',p_wager_amount,'game',p_game,'affiliate',v_affiliate,'rollover',v_rollover); insert into public.wager_progress_ledger(user_id,wager_ref,wager_amount,game,result) values(p_user_id,trim(p_wager_ref),p_wager_amount,p_game,v_result); return v_result; end; $$;
create or replace function public.apply_wager_progress(p_user_id uuid,p_wager_amount numeric) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin return public.record_wager_effects(p_user_id,p_wager_amount,'legacy:'||p_user_id::text||':'||gen_random_uuid()::text,'legacy',0.005); end; $$;
create or replace function public._distribute_affiliate_commission(p_affiliate_user_id uuid,p_referred_user_id uuid,p_wager_amount numeric,p_commission_amount numeric,p_wager_ref text,p_game text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare v_rate numeric; v_result jsonb; begin if coalesce(p_wager_amount,0)<=0 then return; end if; v_rate:=greatest(0,coalesce(p_commission_amount,0)/p_wager_amount); v_result:=public.credit_affiliate_wager_commission_atomic(p_referred_user_id,p_wager_amount,p_wager_ref,p_game,v_rate); if coalesce(v_result->>'ok','false')<>'true' then raise exception 'AFFILIATE_COMMISSION_FAILED'; end if; end; $$;
